  var renderMarkdown = MarkdownRenderer.renderMarkdown;
  var renderListItem = MarkdownRenderer.renderListItem;
  var splitSentences = MarkdownRenderer.splitSentences;
  var parsePoint = MarkdownRenderer.parsePoint;

